"use strict";

/**
 * 本站重写的雪花特效，用来替换主题自带的 snow.min.js。
 *
 * 主题原版的四个问题：
 * 1. CSS 里 #snow:not(.disabled) 带了一层 hsla(0,0%,88%,.05) 的浅灰底，
 *    透明度一旦失效（部分浏览器、强制配色、扩展干扰）就退化成不透明的
 *    rgb(224,224,224)，整屏被糊白，什么都看不见；
 * 2. 每次重新开启都往数组里 push 新粒子、旧的不清空，越切越卡；
 * 3. 关闭时旧粒子坐标留在原地，再次开启时雪花从旧位置继续落；
 * 4. 画布按 CSS 像素建图，高 DPI 屏上雪花发虚。
 *
 * 本实现：背景完全交给 CSS 保持透明，每次开启重建粒子，关闭即停并清空，
 * 按 devicePixelRatio 建图，并按当前主题调整雪花颜色——浅色模式下用淡蓝灰，
 * 不至于白点落在白底上完全看不见。
 */

(function () {
  var STORE_KEY = "kr-disable-snow";
  var COUNT = 90;
  var INFLUENCE = 12000; // 鼠标推开雪花的作用半径平方（约 110px）

  var canvas = document.getElementById("snow");
  if (!canvas || !canvas.getContext) return;

  var ctx = canvas.getContext("2d");
  if (!ctx) return;

  var flakes = [];
  var running = false;
  var rafId = 0;
  var mouseX = -9999;
  var mouseY = -9999;
  var resizeTimer = 0;

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var isMobile = !!(window.kr && window.kr.notMobile === false);

  function seed() {
    var w = window.innerWidth;
    var h = window.innerHeight;
    flakes = [];
    for (var i = 0; i < COUNT; i++) {
      flakes.push({
        x: Math.random() * w,
        y: Math.random() * h,
        r: Math.random() * 1.9 + 1.3,
        vy: Math.random() * 0.8 + 0.45,
        drift: (Math.random() - 0.5) * 0.5,
        phase: Math.random() * Math.PI * 2,
        alpha: Math.random() * 0.4 + 0.35,
      });
    }
  }

  function resizeCanvas() {
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(window.innerWidth * dpr);
    canvas.height = Math.round(window.innerHeight * dpr);
    // 之后所有绘制都用 CSS 像素坐标，由变换矩阵负责放大
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    seed();
  }

  function draw() {
    var w = window.innerWidth;
    var h = window.innerHeight;
    var dark = document.documentElement.getAttribute("data-theme") === "dark";
    // 浅色模式用淡蓝灰，深色模式用纯白，两边都能看清
    var rgb = dark ? "255,255,255" : "122,172,222";

    ctx.clearRect(0, 0, w, h);

    for (var i = 0; i < flakes.length; i++) {
      var f = flakes[i];

      f.phase += 0.018;
      f.y += f.vy;
      f.x += f.drift + Math.cos(f.phase) * 0.3;

      // 鼠标经过时把雪花轻轻推开，避免粒子糊在光标上
      var dx = f.x - mouseX;
      var dy = f.y - mouseY;
      var d2 = dx * dx + dy * dy;
      if (d2 < INFLUENCE && d2 > 1) {
        var d = Math.sqrt(d2);
        f.x += (dx / d) * 1.2;
        f.y += (dy / d) * 1.2;
      }

      if (f.y > h + 8) {
        f.y = -8;
        f.x = Math.random() * w;
      }
      if (f.x < -8) f.x = w + 8;
      if (f.x > w + 8) f.x = -8;

      ctx.beginPath();
      ctx.fillStyle = "rgba(" + rgb + "," + f.alpha + ")";
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    }

    rafId = window.requestAnimationFrame(draw);
  }

  function start() {
    if (running) return;
    running = true;
    canvas.classList.remove("disabled");
    seed(); // 每次开启都重新生成，彻底避免粒子累积
    rafId = window.requestAnimationFrame(draw);
  }

  function stop() {
    running = false;
    if (rafId) window.cancelAnimationFrame(rafId);
    rafId = 0;
    canvas.classList.add("disabled");
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
  }

  resizeCanvas();

  var enabled = true;
  try {
    enabled = localStorage.getItem(STORE_KEY) === null;
  } catch (error) {
    enabled = true;
  }
  // 减弱动效偏好和移动端都不自动开启，但按钮仍然可以手动打开
  if (reduceMotion || isMobile) enabled = false;

  if (enabled) start();
  else stop();

  var switchButton = document.getElementById("snow-switch");
  if (switchButton) {
    switchButton.addEventListener("click", function () {
      if (running) {
        stop();
        try {
          localStorage.setItem(STORE_KEY, "true");
        } catch (error) {
          /* 无痕模式下存不了，本次会话仍然生效 */
        }
      } else {
        start();
        try {
          localStorage.removeItem(STORE_KEY);
        } catch (error) {
          /* 同上 */
        }
      }
    });
  }

  document.addEventListener(
    "mousemove",
    function (event) {
      mouseX = event.clientX;
      mouseY = event.clientY;
    },
    { passive: true }
  );

  document.addEventListener("mouseleave", function () {
    mouseX = -9999;
    mouseY = -9999;
  });

  window.addEventListener("resize", function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(resizeCanvas, 180);
  });
})();
